  });

  return (
    <header className="header">
      <div className="org-logo"></div>
      <div className="site-info">
        <div className="site-org">Organization Name</div>
        <div className="site-description">a service of the Some-team-or-another</div>
      </div>
      <nav className="nav">
        <div className="link"><Link to="/">Home</Link></div>
        <div className="link"><Link to="/ScopeFull">Chesapeake Bay Watershed</Link></div>
        <div className="link"><Link to="/ScopeVA">Virginia Only</Link></div>
      </nav>
    </header>
  );
};

export default Header;
